def check(nums):
    n = len(nums)
    drops = 0  # count positions where nums[i] > nums[(i+1)%n]
    for i in range(n):
        next_i = (i + 1) % n  # wrap-around for circular check
        if nums[i] > nums[next_i]:
            drops += 1
            # More than one drop => not a sorted and rotated array
            if drops > 1:
                return False
    return True
